 internal PortraitReader? Portraits {get;set;}private readonly IModRegistry registry;private readonly CatalogAssets assets;private readonly Func<string,CatalogRelation[]?>? relations;private readonly Func<string[]>? relationNotes;
 private readonly int owner=Environment.CurrentManagedThreadId;private IEnumerator<bool>? itemWork,peopleWork;private long itemVersion=1,peopleVersion=1,peopleAt;private string language="",itemFingerprint="",peopleFingerprint="";private int turn,itemBytes,peopleBytes;private string[] originIds=Array.Empty<string>();private bool npcIndexBuilt,originsCaptured;private readonly Dictionary<(string,string),int?> giftTastes=new();private readonly Dictionary<string,NPC> npcIndex=new(StringComparer.Ordinal);
