 public void InvalidatePeople(string lang){if(Environment.CurrentManagedThreadId!=owner)throw new InvalidOperationException("Game thread required");peopleWork?.Dispose();peopleWork=null;peopleFingerprint="";peopleAt=0;People.Publish(new("people",++peopleVersion,lang,"building",Array.Empty<object>(),Array.Empty<string>(),new(0,0)));}
 public void Invalidate(string lang,bool textures=false){if(Environment.CurrentManagedThreadId!=owner)throw new InvalidOperationException("Game thread required");itemWork?.Dispose();peopleWork?.Dispose();itemWork=peopleWork=null;language=lang;itemFingerprint=peopleFingerprint="";peopleAt=0;originsCaptured=false;giftTastes.Clear();npcIndexBuilt=false;npcIndex.Clear();Items.Publish(new("items",++itemVersion,lang,"building",Array.Empty<object>(),Array.Empty<string>(),new(0,0)));People.Publish(new("people",++peopleVersion,lang,"building",Array.Empty<object>(),Array.Empty<string>(),new(0,0)));if(textures)assets.Invalidate();}
