 public void Tick(string lang){if(Environment.CurrentManagedThreadId!=owner)throw new InvalidOperationException("Game thread required");if(lang!=language)Invalidate(lang,true);var watch=Stopwatch.StartNew();for(int i=0;i<64&&watch.Elapsed.TotalMilliseconds<1.5;i++){
   bool items=Items.Wanted&&(turn++%2==0||!People.Wanted);if(items){if(itemFingerprint.Length>0)continue;try{itemWork??=BuildItems().GetEnumerator();if(!itemWork.MoveNext()){itemWork.Dispose();itemWork=null;SheetPixels.Release();}}catch{itemWork?.Dispose();itemWork=null;itemFingerprint="unsupported";Items.Publish(new("items",++itemVersion,lang,"unsupported",Array.Empty<object>(),new[]{"catalog-source-unavailable"}));}}
   else if(People.Wanted){if(peopleWork==null&&peopleFingerprint.Length>0&&BridgeServer.Age(peopleAt)<5000)continue;try{peopleWork??=BuildPeople().GetEnumerator();if(!peopleWork.MoveNext()){peopleWork.Dispose();peopleWork=null;peopleAt=Stopwatch.GetTimestamp();}}catch{peopleWork?.Dispose();peopleWork=null;peopleAt=Stopwatch.GetTimestamp();peopleFingerprint="unsupported";People.Publish(new("people",++peopleVersion,lang,"unsupported",Array.Empty<object>(),new[]{"catalog-source-unavailable"}));}}
