 private IEnumerable<bool> BuildItems(){var limited=new HashSet<string>(StringComparer.Ordinal);var ids=new List<(IItemDataDefinition Type,string Id)>();var seen=new HashSet<string>(StringComparer.Ordinal);int scanned=0;
