    if(d.Description==null)limited.Add("catalog-description-unavailable");var row=new CatalogItem(d.QualifiedItemId,ReadOnlyMetadata.Limit(d.DisplayName,240,limited),ReadOnlyMetadata.Limit(d.Description,1200,limited),ReadOnlyMetadata.Limit(d.ObjectType=="Arch"?Game1.content.LoadString("Strings\\StringsFromCSFiles:Object.cs.12849"):StardewValley.Object.GetCategoryDisplayName(d.Category),120,limited),d.Category,ReadOnlyMetadata.Price(d,limited),assets.Item(d,limited),ReadOnlyMetadata.Type(type.Identifier),ModOrigin(d.ItemId),d.RawData is StardewValley.GameData.Objects.ObjectData o&&o.Edibility>=0,recipes.GetValueOrDefault(d.QualifiedItemId));Add(entries,row,limited);
   }}catch{limited.Add("catalog-item-unsupported");}done++;if(done%16==0)Items.Publish(new("items",itemVersion,language,"building",Array.Empty<object>(),Notes(limited),new(done,ids.Count)));yield return true;}
  PublishItems(entries,limited);
 }
 private IEnumerable<bool> BuildPeople(){var limited=new HashSet<string>(StringComparer.Ordinal);var entries=new List<object>();peopleBytes=0;using var hash=System.Security.Cryptography.IncrementalHash.CreateHash(System.Security.Cryptography.HashAlgorithmName.SHA256);var data=Game1.characterData;int done=0,total=Math.Min(data.Count,CatalogDirectory.MaxPeople);if(data.Count>total)limited.Add("catalog-people-limit");if(!originsCaptured)foreach(var _ in CaptureOrigins(limited))yield return true;
  if(!npcIndexBuilt&&Context.IsWorldReady){foreach(var _ in BuildNpcIndex(limited))yield return true;npcIndexBuilt=true;}
  foreach(var pair in data.Take(total)){var p=pair.Value;var known=new Dictionary<int,List<string>>{{0,new()},{2,new()},{4,new()},{6,new()},{8,new()}};
   if(Context.IsWorldReady&&Game1.player.giftedItems.TryGetValue(pair.Key,out var gifts)){int n=0;foreach(var gift in gifts.Keys){if(n++>=64){limited.Add("catalog-gifts-limit");break;}try{var item=ItemRegistry.GetData(gift);if(item!=null&&item.QualifiedItemId.Length<=160){var tasteKey=(pair.Key,item.QualifiedItemId);if(!giftTastes.TryGetValue(tasteKey,out var taste)){taste=ReadOnlyMetadata.GiftTaste(pair.Key,item,limited);if(giftTastes.Count<32768)giftTastes[tasteKey]=taste;}if(taste==null)limited.Add("gifts-unsupported");if(taste==7)taste=0;if(taste!=null)known[taste.Value].Add(item.QualifiedItemId);}}catch{limited.Add("gifts-unsupported");}yield return true;}limited.Add("gifts-instance-overrides-unverified");}
   try{var npc=npcIndex.GetValueOrDefault(pair.Key);string? portrait=Portraits?.Read(pair.Key,npc,limited);if(Portraits==null&&npc?.Portrait is {} texture)portrait=assets.Read(texture,new Rectangle(0,0,64,64),limited);if(portrait==null)limited.Add("catalog-portrait-unavailable");CatalogBirthday? birthday=p.BirthSeason!=null&&p.BirthDay is >=1 and <=28?new(p.BirthSeason.Value.ToString().ToLowerInvariant(),p.BirthDay):null;
    var row=new CatalogPerson(ReadOnlyMetadata.Limit(pair.Key,160,limited),ReadOnlyMetadata.Limit(TokenParser.ParseText(p.DisplayName),240,limited),birthday,p.SocialTab.ToString() switch{"AlwaysShown"=>"alwaysShown","HiddenUntilMet"=>"hiddenUntilMet","HiddenAlways"=>"hiddenAlways",_=>"unknownUntilMet"},(npc?.IsVillager??true)&&SafeProgressQuery.Check(p.CanSocialize,limited),p.CanBeRomanced,portrait,ReadOnlyMetadata.Limit(p.HomeRegion,160,limited),ModOrigin(pair.Key),new(known[0].Distinct().ToArray(),known[2].Distinct().ToArray(),known[8].Distinct().ToArray(),known[4].Distinct().ToArray(),known[6].Distinct().ToArray()),relations?.Invoke(pair.Key));Add(entries,row,limited);hash.AppendData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(row,BridgeServer.Json)));
