 private void PublishItems(List<object> entries,HashSet<string> limited){itemFingerprint="ready";Items.Publish(new("items",++itemVersion,language,"ready",entries.ToArray(),Notes(limited)));}
 private void Add(List<object> entries,object value,ISet<string> limited){int bytes=Encoding.UTF8.GetByteCount(JsonSerializer.Serialize(value,BridgeServer.Json));if(bytes>CatalogDirectory.EntryBudget){limited.Add("catalog-entry-bytes");return;}ref int used=ref (value is CatalogPerson?ref peopleBytes:ref itemBytes);if(used+bytes>CatalogDirectory.MetadataBudget){limited.Add("catalog-metadata-bytes");return;}used+=bytes;entries.Add(value);}
 private IEnumerable<bool> BuildNpcIndex(ISet<string> limited){var places=new Queue<GameLocation>(Game1.locations.Take(512));var seen=new HashSet<string>(StringComparer.Ordinal);var active=new HashSet<string>(StringComparer.Ordinal);int reads=0;while(places.TryDequeue(out var source)){var place=Game1.currentLocation?.NameOrUniqueName==source.NameOrUniqueName?Game1.currentLocation:source;if(!seen.Add(place.NameOrUniqueName))continue;if(seen.Count>512){limited.Add("catalog-npc-locations-limit");break;}int interiors=0;place.ForEachInstancedInterior(interior=>{if(interiors++>=128){limited.Add("catalog-npc-interiors-limit");return false;}places.Enqueue(interior);return true;});yield return true;foreach(var npc in place.characters){if(reads++>=8192){limited.Add("catalog-npc-source-limit");yield break;}if(npc.Name.Length<=160&&!npc.EventActor&&!active.Contains(npc.Name)){npcIndex[npc.Name]=npc;if(npc.currentLocation?.IsActiveLocation()??false)active.Add(npc.Name);}yield return true;}}
