 private IEnumerable<bool> CaptureOrigins(ISet<string> limited){var ids=new List<string>();foreach(var mod in registry.GetAll()){if(ids.Count>=512){limited.Add("catalog-mod-origin-limit");break;}var id=mod.Manifest.UniqueID;if(id.Length<=160)ids.Add(id);else limited.Add("catalog-mod-origin-limit");yield return true;}originIds=ids.OrderByDescending(s=>s.Length).ToArray();originsCaptured=true;}
